actions.script:
// Resilient dynamic class resolution to eliminate compile-time ClassNotFound errors
GroovyClassLoader gcl = ec.factory.getGroovyClassLoader() ?: new GroovyClassLoader(Thread.currentThread().contextClassLoader ?: ec.class.classLoader)
String compPath = ec.factory.getRuntimePath() + "/component/data-reconciler"
Class codeScannerClass = gcl.parseClass(new File(compPath + "/src/main/groovy/co/hotwax/reconciler/CodeReferenceScanner.groovy"))
Class serviceScannerClass = gcl.parseClass(new File(compPath + "/src/main/groovy/co/hotwax/reconciler/ServiceContractScanner.groovy"))
Class validatorClass = gcl.parseClass(new File(compPath + "/src/main/groovy/co/hotwax/reconciler/ServiceIntegrityValidator.groovy"))
Class testRunnerClass = gcl.parseClass(new File(compPath + "/src/main/groovy/co/hotwax/reconciler/ComponentTestSuiteRunner.groovy"))
Class scannerClass = gcl.parseClass(new File(compPath + "/src/main/groovy/co/hotwax/reconciler/GitDiffScanner.groovy"))
Class resolverClass = gcl.parseClass(new File(compPath + "/src/main/groovy/co/hotwax/reconciler/DockerConfigReleaseResolver.groovy"))
gcl.parseClass(new File(compPath + "/src/main/groovy/co/hotwax/reconciler/RemoteInstanceClient.groovy"))
Class engineClass = gcl.parseClass(new File(compPath + "/src/main/groovy/co/hotwax/reconciler/ReconcileEngine.groovy"))

List<String> entities = entityList.split(",").collect { it.trim() }.findAll { !it.isEmpty() }
String token = scannerClass.resolveGithubToken(githubToken)
String configRepo = dockerConfigRepo ?: "hotwax/hotwax-maarg-docker-config"

// 1. Resolve component shifts from maarg-docker-config
List shifts = []
if (fromTag && toTag) {
    shifts = resolverClass.resolveShifts(configRepo, fromTag, toTag, token)
}

// 2. Fetch Git Diff across all shifted components from GitHub Compare API
Map<String, Map<String, Map<String, String>>> allGitAdditions = [:]
Map<String, String> entityPkOrigins = [:]
List<Map> rawCodeRefs = []
def serviceCtx = serviceScannerClass.createContext()
for (String entity : entities) allGitAdditions[entity] = [:]

if (shifts) {
    for (def shift : shifts) {
        if (shift.fromTag && shift.toTag && shift.repo) {
            Map compDiff = scannerClass.scanGitHubDiff(
                shift.repo, token, shift.fromTag, shift.toTag, entities, shift.name, rawCodeRefs, serviceCtx
            )
            for (String entity : entities) {
                Map compEntityMap = compDiff[entity] ?: [:]
                for (Map.Entry entry : compEntityMap.entrySet()) {
                    allGitAdditions[entity].put(entry.key, entry.value)
                    entityPkOrigins.put("${entity}::${entry.key}", "${shift.name} (${shift.fromTag} -> ${shift.toTag})")
                }
            }
        }
    }
} else if (fromTag && toTag && (githubRepo || repoPath)) {
    // Fallback to direct repo if no docker-config shifts found
    allGitAdditions = scannerClass.scanDiff(githubRepo, token, repoPath, fromTag, toTag, entities)
}

Map results = [:]
int totalCritical = 0
int totalEnv = 0
int totalApplied = 0
StringBuilder fullXml = new StringBuilder()
StringBuilder report = new StringBuilder()

String targetDisplay = targetUrl && !targetUrl.equalsIgnoreCase("local") ? targetUrl : "Local Database"
report.append("================================================================================\n")
report.append("                    AUTOMATED RELEASE RECONCILIATION REPORT                     \n")
report.append("================================================================================\n")
report.append("Reference (Source) : ${referenceUrl}\n")
report.append("Target Instance    : ${targetDisplay}\n")
report.append("Docker Config Tag  : ${fromTag ?: 'N/A'} -> ${toTag ?: 'N/A'} (${configRepo})\n")
report.append("Auto-Apply         : ${autoApply}\n")
report.append("Shifted Components : ${shifts ? shifts.size() : 0} shifted components detected\n")
report.append("================================================================================\n\n")

List<Map> tableRows = []
for (String entity : entities) {
    Map entityGitMap = allGitAdditions[entity] ?: [:]
    Map entityRes = engineClass.reconcileEntity(
        ec, referenceUrl, referenceApiKey, targetUrl, targetApiKey, entity, entityGitMap, entityPkOrigins, autoApply
    )

    int crit = (entityRes.criticalMissingList as List).size()
    int env = (entityRes.environmentMissingList as List).size()
    int applied = (entityRes.autoAppliedCount as Integer)

    // Strip environment noise from output map so only missing data is returned
    entityRes.remove("environmentMissingList")
    results.put(entity, entityRes)

    totalCritical += crit
    totalEnv += env
    totalApplied += applied

    if (entityRes.syncXmlPayload) {
        fullXml.append(entityRes.syncXmlPayload)
    }

    if (crit > 0) {
        tableRows.add([entity: entity, missing: crit, applied: applied])
    }
}

// Render clean aligned ASCII table
report.append("+------------------------------------------+------------------+--------------+\n")
report.append(String.format("| %-40s | %16s | %12s |\n", "Entity Name", "Critical Missing", "Auto-Applied"))
report.append("+------------------------------------------+------------------+--------------+\n")
if (tableRows) {
    for (Map row : tableRows) {
        report.append(String.format("| %-40s | %16d | %12d |\n", row.entity, row.missing, row.applied))
    }
} else {
    report.append(String.format("| %-40s | %16d | %12d |\n", "All Target Entities (In Sync)", 0, 0))
}
report.append("+------------------------------------------+------------------+--------------+\n")
report.append(String.format("| %-40s | %16d | %12d |\n", "TOTAL CRITICAL MISSING", totalCritical, totalApplied))
report.append("+------------------------------------------+------------------+--------------+\n\n")

// Add detailed critical missing breakdown with correct Primary Key extraction
if (totalCritical > 0) {
    report.append("================================================================================\n")
    report.append("                       CRITICAL MISSING RECORDS BREAKDOWN                       \n")
    report.append("================================================================================\n\n")

    for (String entity : entities) {
        List<Map> critList = results[entity]?.criticalMissingList as List<Map>
        if (critList) {
            String pkField = engineClass.getPkFieldName(entity)
            report.append("[ ${entity} ] (${critList.size()} items missing)\n")
            report.append("--------------------------------------------------------------------------------\n")
            int itemIdx = 1
            for (Map rec : critList) {
                String pkVal = rec.get(pkField) ?: rec.get("enumId") ?: rec.get("statusId") ?: rec.get("enumTypeId") ?: rec.get("systemMessageTypeId") ?: rec.get("id")
                String typeVal = rec.get("enumTypeId") ?: rec.get("statusTypeId") ?: rec.get("parentTypeId")
                String desc = rec.get("description") ?: rec.get("name") ?: ""
                String origin = rec.get("_introducedBy") ?: "Git Diff"

                if (typeVal && !typeVal.isEmpty() && !typeVal.equals(pkVal)) {
                    report.append(String.format("  %2d. %s  (Type: %s)\n", itemIdx, pkVal, typeVal))
                } else {
                    report.append(String.format("  %2d. %s\n", itemIdx, pkVal))
                }
                if (desc) {
                    report.append("      - Description : ${desc}\n")
                }
                report.append("      - Introduced  : ${origin}\n\n")
                itemIdx++
            }
        }
    }
}

// 3. Verify developer omissions (Ghost enums/statuses referenced in code but missing from XML/DB)
List<Map<String, Object>> omissions = (List<Map<String, Object>>) codeScannerClass.verifyOmissions(
    rawCodeRefs, allGitAdditions, ec, referenceUrl
)

if (omissions) {
    report.append("================================================================================\n")
    report.append("       DEVELOPER OMISSION ALERTS (Referenced in Code, Missing from Data/DB)     \n")
    report.append("================================================================================\n")
    report.append("Found ${omissions.size()} references used in code conditions/assignments without seed/upgrade data:\n\n")
    int oIdx = 1
    for (Map alert : omissions) {
        report.append("  ${oIdx}. ${alert.candidateId} (${alert.probableEntity})\n")
        report.append("      - Component   : ${alert.component} (${alert.repo})\n")
        report.append("      - File        : ${alert.filePath}\n")
        report.append("      - Code Line   : ${alert.codeSnippet}\n")
        report.append("      - Suggested Fix XML:\n")
        report.append("        ${alert.suggestedXml}\n\n")
        oIdx++
    }
}

// 4. Phase 1: Service Contract & Breaking Change Audit
serviceScannerClass.verifyServiceDefinitions(ec, serviceCtx)
List<Map<String, Object>> breakingChanges = (List<Map<String, Object>>) serviceCtx.breakingChanges
List<Map<String, Object>> newServices = (List<Map<String, Object>>) serviceCtx.newServices
List<Map<String, Object>> deletedServices = (List<Map<String, Object>>) serviceCtx.deletedServices

if (breakingChanges || newServices || deletedServices) {
    report.append("================================================================================\n")
    report.append("                    SERVICE CONTRACT & BREAKING CHANGE AUDIT                    \n")
    report.append("================================================================================\n")
    report.append(String.format("  - Breaking Contract Changes  : %d\n", breakingChanges.size()))
    report.append(String.format("  - New Services Introduced    : %d\n", newServices.size()))
    report.append(String.format("  - Services Deleted / Renamed : %d\n", deletedServices.size()))
    report.append("--------------------------------------------------------------------------------\n\n")

    if (breakingChanges) {
        report.append("[ 🚨 BREAKING CONTRACT ALERTS - ACTION REQUIRED BEFORE GOING LIVE! ]\n")
        int bcIdx = 1
        for (Map bc : breakingChanges) {
            report.append(String.format("  %2d. Service: %s\n", bcIdx, bc.serviceName))
            report.append("      - Component : ${bc.component} (${bc.repo})\n")
            report.append("      - File      : ${bc.filePath}\n")
            report.append("      - Severity  : ${bc.severity}\n")
            report.append("      - Problem   : ${bc.message}\n\n")
            bcIdx++
        }
    }

    if (deletedServices) {
        report.append("[ ⚠️ DELETED / RENAMED SERVICES ]\n")
        int delIdx = 1
        for (Map ds : deletedServices) {
            report.append(String.format("  %2d. Service: %s (%s)\n", delIdx, ds.serviceName, ds.component))
            report.append("      - File: ${ds.filePath}\n\n")
            delIdx++
        }
    }

    if (newServices) {
        report.append("[ ✨ NEW SERVICES INTRODUCED (${newServices.size()}) ]\n")
        int nsIdx = 1
        for (Map ns : newServices) {
            report.append(String.format("  %2d. %s  [%s]\n", nsIdx, ns.serviceName, ns.component))
            report.append("      - File   : ${ns.filePath}\n")
            report.append("      - Status : ${ns.loadStatus ?: 'PENDING'}\n\n")
            nsIdx++
        }
    }
}

// 5. Phase 2: Deep Service Integrity & Scheduled Job Pre-Flight Audit
def phase2Result = validatorClass.runAudit(ec, serviceCtx)
List<Map<String, Object>> brokenJobs = (List<Map<String, Object>>) phase2Result.brokenScheduledJobAlerts
List<Map<String, Object>> scriptAlerts = (List<Map<String, Object>>) phase2Result.scriptLocationAlerts

if (brokenJobs || scriptAlerts || phase2Result.totalScriptsVerified > 0 || phase2Result.totalScheduledJobsAudited > 0) {
    report.append("================================================================================\n")
    report.append("               PHASE 2: DEEP SERVICE INTEGRITY & PRE-FLIGHT AUDIT               \n")
    report.append("================================================================================\n")
    report.append(String.format("  - Service Scripts Verified on Disk : %d\n", phase2Result.totalScriptsVerified))
    report.append(String.format("  - Script Location Alerts           : %d\n", scriptAlerts.size()))
    report.append(String.format("  - Scheduled Jobs Audited           : %d\n", phase2Result.totalScheduledJobsAudited))
    report.append(String.format("  - At-Risk Scheduled Jobs           : %d\n", brokenJobs.size()))
    report.append("--------------------------------------------------------------------------------\n\n")

    if (brokenJobs) {
        report.append("[ 🚨 AT-RISK SCHEDULED JOBS (WILL FAIL ON NEXT CRON RUN!) ]\n")
        int bjIdx = 1
        for (Map bj : brokenJobs) {
            report.append(String.format("  %2d. Job Name      : %s (Active, Paused: %s)\n", bjIdx, bj.jobName, bj.paused))
            report.append("      - Service       : ${bj.serviceName}\n")
            report.append("      - Missing Param : ${bj.missingParam} (required=\"true\")\n")
            report.append("      - Component     : ${bj.component}\n")
            report.append("      - Impact        : ${bj.message}\n\n")
            bjIdx++
        }
    }

    if (scriptAlerts) {
        report.append("[ ⚠️ SCRIPT LOCATION ALERTS (FILE NOT FOUND ON DISK) ]\n")
        int slIdx = 1
        for (Map sl : scriptAlerts) {
            report.append(String.format("  %2d. Service   : %s (%s)\n", slIdx, sl.serviceName, sl.component))
            report.append("      - Location : ${sl.location}\n")
            report.append("      - Problem  : ${sl.message}\n\n")
            slIdx++
        }
    }
}

// 6. Phase 3: Automated Test Execution & Smoke Testing
def phase3Result = testRunnerClass.runAudit(ec, shifts, serviceCtx, runAutomatedTests == true, testComponentList)
List suiteResults = (List) phase3Result.suiteResults
List smokeResults = (List) phase3Result.smokeTestResults

if (phase3Result.totalSuitesDiscovered > 0 || phase3Result.totalSmokeTestsRun > 0) {
    report.append("================================================================================\n")
    report.append("               PHASE 3: AUTOMATED TEST SUITE RUNNER & SMOKE AUDIT               \n")
    report.append("================================================================================\n")
    report.append(String.format("  - Test Suites Discovered           : %d\n", phase3Result.totalSuitesDiscovered))
    report.append(String.format("  - Total Tests Discovered           : %d\n", phase3Result.totalTestsDiscovered))
    report.append(String.format("  - Automated Tests Run              : %d\n", phase3Result.totalTestsExecuted))
    report.append(String.format("  - Tests Passed                     : %d\n", phase3Result.totalTestsPassed))
    report.append(String.format("  - Tests Failed                     : %d\n", phase3Result.totalTestsFailed))
    report.append(String.format("  - Service Smoke Tests Run          : %d\n", phase3Result.totalSmokeTestsRun))
    report.append(String.format("  - Smoke Tests Passed               : %d\n", phase3Result.totalSmokeTestsPassed))
    report.append(String.format("  - Smoke Tests Failed               : %d\n", phase3Result.totalSmokeTestsFailed))
    report.append("--------------------------------------------------------------------------------\n\n")

    if (suiteResults) {
        report.append("[ 🧪 COMPONENT TEST SUITES DISCOVERED ]\n")
        int tsIdx = 1
        for (def ts : suiteResults) {
            report.append(String.format("  %2d. [%s] %s (%s, %d tests)\n", tsIdx, ts.componentName, ts.testClassName, ts.testFramework, ts.totalTests))
            report.append("      - Path   : ${ts.relativePath}\n")
            report.append("      - Status : ${ts.status}\n")
            if (ts.featureNames) {
                report.append("      - Features: ${ts.featureNames.take(3).join(', ')}${ts.featureNames.size() > 3 ? ' ... (' + (ts.featureNames.size() - 3) + ' more)' : ''}\n")
            }
            if (ts.failureDetails) {
                for (Map fd : ts.failureDetails) {
                    report.append("      - ERROR: ${fd.error}: ${fd.message}\n")
                }
            }
            report.append("\n")
            tsIdx++
        }
    }

    if (smokeResults) {
        report.append("[ 💨 SERVICE DRY-RUN SMOKE TESTS ]\n")
        int smIdx = 1
        for (Map sm : smokeResults) {
            report.append(String.format("  %2d. %s (%s) -> %s\n", smIdx, sm.serviceName, sm.component, sm.status))
            report.append("      - Details: ${sm.message}\n")
            if (sm.durationMs) {
                report.append("      - Duration: ${sm.durationMs}ms\n")
            }
            report.append("\n")
            smIdx++
        }
    }
}

if (brokenJobs.size() > 0) {
    overallStatus = "CRITICAL_SCHEDULED_JOBS_AT_RISK"
} else if (phase3Result.totalTestsFailed > 0 || phase3Result.totalSmokeTestsFailed > 0) {
    overallStatus = "AUTOMATED_TESTS_FAILED"
} else if (scriptAlerts.size() > 0) {
    overallStatus = "SERVICE_SCRIPTS_MISSING"
} else if (breakingChanges.size() > 0) {
    overallStatus = "BREAKING_SERVICE_CHANGES_FOUND"
} else if (totalCritical > 0 && omissions.size() > 0) {
    overallStatus = "CRITICAL_MISSING_AND_OMISSIONS_FOUND"
} else if (totalCritical > 0) {
    overallStatus = autoApply ? "AUTO_REPAIRED" : "CRITICAL_MISSING_FOUND"
} else if (omissions.size() > 0) {
    overallStatus = "DEVELOPER_OMISSION_DETECTED"
} else {
    overallStatus = "IN_SYNC"
}

report.append("================================================================================\n")
report.append("                              RECONCILIATION SUMMARY                            \n")
report.append("================================================================================\n")
report.append(String.format("  - Total Missing Records to Sync : %d\n", totalCritical))
report.append(String.format("  - Total Developer Code Omissions: %d\n", omissions.size()))
report.append(String.format("  - Service Breaking Changes      : %d\n", breakingChanges.size()))
report.append(String.format("  - At-Risk Scheduled Jobs        : %d\n", brokenJobs.size()))
report.append(String.format("  - Test Suites Discovered        : %d\n", phase3Result.totalSuitesDiscovered))
report.append(String.format("  - Automated Tests Executed      : %d (Passed: %d, Failed: %d)\n", phase3Result.totalTestsExecuted, phase3Result.totalTestsPassed, phase3Result.totalTestsFailed))
report.append(String.format("  - Total Auto-Applied to Database: %d\n", totalApplied))
report.append(String.format("  - Overall Status                : %s\n", overallStatus))
report.append("================================================================================\n")

totalCriticalMissing = totalCritical
totalEnvironmentMissing = totalEnv
totalAutoApplied = totalApplied
shiftedComponentsCount = shifts.size()
totalOmissionAlerts = omissions.size()
omissionAlerts = omissions
totalServiceBreakingChanges = breakingChanges.size()
serviceBreakingChanges = breakingChanges
newServicesIntroduced = newServices
totalAtRiskScheduledJobs = brokenJobs.size()
atRiskScheduledJobs = brokenJobs
scriptLocationAlerts = scriptAlerts
totalTestSuitesDiscovered = phase3Result.totalSuitesDiscovered
totalTestsDiscovered = phase3Result.totalTestsDiscovered
totalTestsExecuted = phase3Result.totalTestsExecuted
totalTestsPassed = phase3Result.totalTestsPassed
totalTestsFailed = phase3Result.totalTestsFailed
testSuiteResults = suiteResults
serviceSmokeTestResults = smokeResults
resultsByEntity = results
combinedSyncXml = fullXml.length() > 0 ? "<entity-facade-xml>\n${fullXml.toString()}</entity-facade-xml>" : ""
summaryReport = report.toString()
